import { createHash } from "node:crypto";
import { assertSceneModuleManifest } from "./scene-module-schema.mjs";

const compare = (left, right) => left < right ? -1 : left > right ? 1 : 0;

function ordered(value) {
  if (Array.isArray(value)) return value.map(ordered);
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(Object.keys(value).sort(compare).map((key) => [key, ordered(value[key])]));
}

export function stableJson(value, space = 2) {
  return JSON.stringify(ordered(value), null, space);
}

function textDigest(value) {
  return `sha256:${createHash("sha256").update(value, "utf8").digest("hex")}`;
}

export function emitSceneModule(compilation, options = {}) {
  const entry = options.entry || "scene.generated.mjs";
  const sourceFiles = compilation.source_files || [{
    file: options.sourceName || "scene.ssdl",
    content: compilation.source,
  }];
  const mapName = options.mapName || `${entry}.map`;
  const payload = {
    bindingIR: compilation.binding_ir,
    sceneIR: compilation.scene_ir,
  };
  const moduleSource = [
    "// Generated by SSDL/QML-Subset/0.3. Do not edit.",
    `export const metadata = Object.freeze(${stableJson({
      sceneModuleVersion: 1,
      sourceKind: "ssdl",
      compilerProfile: compilation.compiler_profile.profile,
      compilerProfileDigest: compilation.compiler_profile_digest,
    })});`,
    `export const sceneIR = Object.freeze(${stableJson(payload.sceneIR)});`,
    `export const bindingIR = Object.freeze(${stableJson(payload.bindingIR)});`,
    "export async function mount(ctx) {",
    "  if (!ctx?.runtime || typeof ctx.runtime.installGraph !== \"function\") {",
    "    throw Object.assign(new Error(\"SceneRuntimeBridge.installGraph is required\"), { code: \"scene_runtime_bridge_missing\" });",
    "  }",
    "  return ctx.runtime.installGraph(sceneIR, bindingIR, { metadata });",
    "}",
    "export function snapshot(instance) { return instance.snapshot(); }",
    "export async function dispose(instance) { await instance.dispose(); }",
    `//# sourceMappingURL=${mapName}`,
    "",
  ].join("\n");
  const sourceMap = {
    version: 3,
    file: entry,
    sources: sourceFiles.map((item) => item.file),
    sourcesContent: sourceFiles.map((item) => item.content),
    names: [],
    mappings: "",
    x_ssdl_entries: compilation.source_map,
    x_source_expansion_map: compilation.expansion_map || null,
  };
  const manifest = assertSceneModuleManifest({
    schema_version: "SceneModuleManifest/1",
    scene_module_version: 1,
    name: options.name || compilation.scene_ir.scope_id,
    entry,
    execution_profiles: options.executionProfiles || ["trusted-local", "agent-mcp"],
    resource_root: ".",
    source_map: mapName,
    scene_ir_version: 5,
    binding_ir_version: 2,
    compiler_profile: compilation.compiler_profile.profile,
    compiler_profile_digest: compilation.compiler_profile_digest,
    catalog_digest: compilation.compiler_profile.catalog_digest,
    runtime_abi_digest: compilation.compiler_profile.runtime_abi_digest,
    scene_ir_digest: compilation.scene_ir_digest,
    binding_ir_digest: compilation.binding_ir_digest,
    module_digest: textDigest(moduleSource),
    budgets: options.budgets || { native_objects: 32, bindings: 32, handlers: 8, timers: 8 },
    ...(compilation.scene_ir.host_interfaces ? { host_interfaces: compilation.scene_ir.host_interfaces } : {}),
  });
  return Object.freeze({
    module: moduleSource,
    source_map: `${stableJson(sourceMap)}\n`,
    manifest: `${stableJson(manifest)}\n`,
  });
}
